CREATE TABLE IF NOT EXISTS WorkflowExecution (id TEXT PRIMARY KEY NOT NULL,ownerId TEXT NOT NULL,operation TEXT NOT NULL,requestKey TEXT NOT NULL,requestHash TEXT NOT NULL,coordinatorId TEXT NOT NULL,protocolVersion INTEGER NOT NULL DEFAULT 1,epoch INTEGER NOT NULL DEFAULT 1,state TEXT NOT NULL,requestJson TEXT NOT NULL,resultRefJson TEXT,expiresAt DATETIME NOT NULL,createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS WorkflowExecution_ownerId_operation_requestKey_key ON WorkflowExecution(ownerId,operation,requestKey);
CREATE TABLE IF NOT EXISTS TaskAttempt (instanceJson TEXT NOT NULL DEFAULT '{}',id TEXT PRIMARY KEY NOT NULL,workflowId TEXT NOT NULL,nodeId TEXT NOT NULL,epoch INTEGER NOT NULL,state TEXT NOT NULL,stopRequestedAt DATETIME,settledAt DATETIME,createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS TaskAttempt_workflowId_nodeId_idx ON TaskAttempt(workflowId,nodeId);
CREATE TABLE IF NOT EXISTS StageCommit (id TEXT PRIMARY KEY NOT NULL,workflowId TEXT NOT NULL,nodeId TEXT NOT NULL,outputVersion INTEGER NOT NULL DEFAULT 1,attemptId TEXT NOT NULL,fencingToken INTEGER NOT NULL,outputRefJson TEXT NOT NULL,createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS StageCommit_workflowId_nodeId_outputVersion_key ON StageCommit(workflowId,nodeId,outputVersion);
CREATE TABLE IF NOT EXISTS ArtifactPin (artifactId TEXT NOT NULL,holderId TEXT NOT NULL,ownerId TEXT NOT NULL,createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(artifactId,holderId));
